import requests
from bs4 import BeautifulSoup
from urllib.parse import urlparse, parse_qs
import sys

def get_video_id(url):
    try:
        query = urlparse(url).query
        video_id = parse_qs(query).get('v')
        if not video_id:
            return None
        return video_id[0]
    except Exception as e:
        print(f"Error parsing URL: {e}")
        return None

def fetch_transcript(video_id):
    try:
        api_url = f"http://video.google.com/timedtext?lang=en&v={video_id}"
        response = requests.get(api_url)

        if response.status_code == 200:
            soup = BeautifulSoup(response.content, 'xml')
            transcript = ''
            for text in soup.find_all('text'):
                transcript += text.get_text(separator=' ') + '\n'
            return transcript if transcript else "Transcript not available for this video."
        else:
            return f"Failed to retrieve transcript. HTTP status code: {response.status_code}"
    except Exception as e:
        return f"Error fetching transcript: {e}"

def main():
    if len(sys.argv) != 2:
        print("Usage: python3 script.py <YouTube Video URL>")
        return

    url = sys.argv[1]
    video_id = get_video_id(url)

    if not video_id:
        print("Invalid YouTube URL or video ID not found.")
        return

    transcript = fetch_transcript(video_id)
    print(transcript)

if __name__ == "__main__":
    main()
